<?php
namespace App\Http\Controllers;
use App\Services\{RoleService,WorkspaceContext as W};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
use Illuminate\Validation\Rule;
class AccessController extends Controller {
 public function index(){W::authorize('roles.view');$roles=RoleService::roles(W::id());$permissions=DB::table('tenant_role_permissions')->where('tenant_id',W::id())->get()->groupBy('role_id');$members=DB::table('memberships')->where('tenant_id',W::id())->select('role_id','role')->get();return view('crm.roles',compact('roles','permissions','members'));}
 public function store(Request $r){W::authorize('roles.manage');$d=$r->validate(['name'=>'required|string|min:3|max:100','permissions'=>'sometimes|array','permissions.*'=>['string',Rule::in(array_keys(config('crm_access.permissions')))]]);$this->verifyGrant($d['permissions']??[]);$slug=Str::slug($d['name']);abort_unless($slug!=='' && !in_array($slug,['owner','admin'],true),422,'Reserved role.');abort_unless(!DB::table('tenant_roles')->where('tenant_id',W::id())->where('slug',$slug)->exists(),422,'A role with this name already exists.');DB::transaction(function()use($d,$slug){$id=DB::table('tenant_roles')->insertGetId(['tenant_id'=>W::id(),'name'=>$d['name'],'slug'=>$slug,'protected'=>false,'created_at'=>now(),'updated_at'=>now()]);$this->replacePermissions($id,$d['permissions']??[]);});return back()->with('success','Role created.');}
 public function update(Request $r,int $id){W::authorize('roles.manage');$role=$this->role($id);abort_unless(!$role->protected,422,'Built-in roles are read-only; create a custom role instead.');$d=$r->validate(['name'=>'required|string|min:3|max:100','permissions'=>'sometimes|array','permissions.*'=>['string',Rule::in(array_keys(config('crm_access.permissions')))]]);$this->verifyGrant($d['permissions']??[]);$existing=DB::table('tenant_role_permissions')->where('tenant_id',W::id())->where('role_id',$id)->pluck('permission')->all();$this->verifyGrant($existing);DB::transaction(function()use($id,$d){DB::table('tenant_roles')->where('tenant_id',W::id())->where('id',$id)->update(['name'=>$d['name'],'updated_at'=>now()]);$this->replacePermissions($id,$d['permissions']??[]);});return back()->with('success','Role permissions updated.');}
 public function delete(int $id){W::authorize('roles.manage');$role=$this->role($id);abort_unless(!$role->protected,422,'System roles cannot be deleted.');abort_unless(!DB::table('memberships')->where('tenant_id',W::id())->where('role_id',$id)->exists(),422,'Reassign members before deleting this role.');$this->verifyGrant(DB::table('tenant_role_permissions')->where('tenant_id',W::id())->where('role_id',$id)->pluck('permission')->all());DB::table('tenant_roles')->where('tenant_id',W::id())->where('id',$id)->delete();return back()->with('success','Role deleted.');}
 private function verifyGrant(array $permissions):void {foreach($permissions as $permission)W::authorize($permission);}
 private function role(int $id){$row=DB::table('tenant_roles')->where('tenant_id',W::id())->where('id',$id)->first();abort_unless($row,404);return $row;}
 private function replacePermissions(int $id,array $permissions):void { $permissions=array_values(array_unique($permissions));DB::table('tenant_role_permissions')->where('tenant_id',W::id())->where('role_id',$id)->delete();foreach($permissions as $permission)DB::table('tenant_role_permissions')->insert(['tenant_id'=>W::id(),'role_id'=>$id,'permission'=>$permission]);}
}
